const css = `:root{color-scheme:dark;--bg:#070a11;--panel:#111624;--panel2:#0c111c;--line:#283247;--text:#f4f6fb;--muted:#8d98ae;--amber:#f5a623;--lime:#d7ff62;--green:#32d49a;--red:#ff6078}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 75% 0,#1b2540 0,transparent 32%),linear-gradient(90deg,#ffffff04 1px,transparent 1px),linear-gradient(#ffffff03 1px,transparent 1px),var(--bg);background-size:auto,72px 72px,72px 72px;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}.shell{max-width:1420px;margin:auto;padding:0 30px}.topbar{min-height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px}.mark{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:var(--amber);color:#15120a;font-weight:950}.brand>span:last-child{display:flex;flex-direction:column;letter-spacing:.14em}.brand small{font:10px ui-monospace,monospace;color:var(--muted);margin-top:3px}.topbar nav{display:flex;align-items:center;gap:24px}.topbar a{color:var(--muted);font-size:12px;text-decoration:none}.topbar a:hover{color:var(--lime)}.connection{display:flex;align-items:center;gap:8px;color:var(--muted);font:10px ui-monospace,monospace}.connection i{width:8px;height:8px;border-radius:50%;background:var(--amber)}.connection i.ok{background:var(--green);box-shadow:0 0 13px var(--green)}.notice{margin-top:18px;border:1px solid #d7ff6244;background:#d7ff6208;border-radius:9px;padding:12px 16px;display:flex;align-items:center;gap:14px;font:11px ui-monospace,monospace;color:var(--muted)}.notice b{color:#10140b;background:var(--lime);border-radius:4px;padding:5px 8px}.notice strong{margin-left:auto;color:var(--green)}.masthead{min-height:285px;display:grid;grid-template-columns:1.45fr .55fr;align-items:end;padding:50px 0 42px;border-bottom:1px solid var(--line)}.eyebrow{color:var(--lime);letter-spacing:.2em;font:700 10px ui-monospace,monospace;margin:0 0 14px}.masthead h1{font-size:clamp(48px,6.6vw,88px);letter-spacing:-.06em;line-height:.89;margin:0;font-weight:500}.masthead h1 em{font-family:Georgia,serif;color:#9aa4bb;font-weight:400}.masthead>p{color:var(--muted);line-height:1.75;margin:0 0 7px}.account{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid var(--line);border-radius:12px;overflow:hidden;margin:24px 0;background:var(--panel2)}.account article{padding:20px;border-right:1px solid var(--line)}.account span,.preview span{display:block;color:var(--muted);font:9px ui-monospace,monospace;letter-spacing:.13em}.account strong{display:block;margin-top:9px;font-size:18px}.market-strip{display:flex;justify-content:space-between;align-items:end;margin:30px 0 18px}.pills{display:flex;flex-wrap:wrap;gap:8px}.pills button{border:1px solid var(--line);background:#101624;color:var(--muted);padding:9px 13px;border-radius:999px;font-weight:700}.pills button.active{border-color:var(--amber);color:var(--text);background:#f5a62316}.ticker{text-align:right}.ticker span{display:block;color:var(--muted);font:11px ui-monospace,monospace}.ticker strong{display:block;font-size:31px;margin:3px 0}.ticker small{color:#68748c;font:9px ui-monospace,monospace;letter-spacing:.12em}.workspace{display:grid;grid-template-columns:1.35fr .65fr;gap:20px}.panel{border:1px solid var(--line);border-radius:15px;background:linear-gradient(145deg,#141a29f0,#0b101af0);padding:26px}.panel-head{display:flex;align-items:flex-start;justify-content:space-between}.panel h2{margin:0 0 22px;font-size:27px;font-weight:500}.stage{color:var(--amber);font:10px ui-monospace,monospace;border:1px solid #f5a62344;border-radius:999px;padding:7px 10px}.side-toggle{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:19px}.side-toggle button{height:44px;border:1px solid var(--line);border-radius:7px;background:#0a0f19;color:var(--muted);font-weight:850}.side-toggle .long.active{background:#32d49a18;border-color:var(--green);color:var(--green)}.side-toggle #short.active{background:#ff607818;border-color:var(--red);color:var(--red)}form{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{color:var(--muted);font:10px ui-monospace,monospace;letter-spacing:.09em}input,select{display:block;width:100%;height:46px;margin-top:7px;border:1px solid var(--line);border-radius:7px;background:#080d16;color:var(--text);padding:0 12px;font:600 14px inherit}input[type=range]{padding:0;accent-color:var(--amber)}output{float:right;color:var(--text)}.split{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;grid-column:1/-1}.primary,.confirm{grid-column:1/-1;height:48px;border:0;border-radius:8px;background:var(--lime);color:#101409;font-weight:900;cursor:pointer}.primary:disabled,.confirm:disabled{opacity:.5}.feedback{margin-top:18px;padding:13px 15px;border-left:2px solid var(--line);background:#080d16;color:var(--muted);font-size:12px}.feedback.error{border-color:var(--red);color:#ff9bab}.feedback.loading{border-color:var(--amber);color:#ffd38a}.preview{display:grid;grid-template-columns:repeat(4,1fr);margin-top:18px;border:1px solid var(--line);border-radius:9px;overflow:hidden}.preview>div{padding:16px;border-right:1px solid var(--line)}.preview strong{display:block;margin-top:8px;font-size:16px}.preview p{grid-column:1/-1;border-top:1px solid var(--line);padding:13px 16px;margin:0;color:var(--muted);font-size:11px}.preview .confirm{margin:0 16px 16px}.risk-list{border-top:1px solid var(--line)}.risk-list div{display:flex;justify-content:space-between;padding:16px 0;border-bottom:1px solid var(--line);gap:15px}.risk-list b{font:10px ui-monospace,monospace;color:var(--muted)}.risk-list span{font-size:12px;text-align:right}.explain{margin-top:22px;padding:17px;border:1px solid #7795ff38;border-radius:9px;background:#7795ff09}.explain p{color:var(--muted);line-height:1.55;font-size:12px;margin:8px 0 0}.book{margin-top:20px}.ghost{border:1px solid var(--line);border-radius:6px;background:transparent;color:var(--muted);padding:8px 11px}.table-wrap{overflow:auto}.data-table{width:100%;border-collapse:collapse;min-width:760px}.data-table th{text-align:left;color:var(--muted);font:9px ui-monospace,monospace;letter-spacing:.12em;padding:10px;border-bottom:1px solid var(--line)}.data-table td{padding:14px 10px;border-bottom:1px solid var(--line);font-size:13px}.data-table button{border:1px solid var(--line);background:#111827;color:var(--text);padding:7px 10px;border-radius:6px}.positive{color:var(--green)}.negative{color:var(--red)}.empty{color:var(--muted);padding:20px 0}footer{display:flex;justify-content:space-between;color:#66728a;font:9px ui-monospace,monospace;letter-spacing:.11em;padding:34px 0}@media(max-width:900px){.masthead{grid-template-columns:1fr;gap:28px}.account{grid-template-columns:1fr 1fr}.workspace{grid-template-columns:1fr}.preview{grid-template-columns:1fr 1fr}}@media(max-width:560px){.shell{padding:0 14px}.topbar nav>a{display:none}.notice span{display:none}.masthead h1{font-size:46px}.account{grid-template-columns:1fr}.market-strip{align-items:flex-start}.ticker strong{font-size:22px}form,.split{grid-template-columns:1fr}.preview{grid-template-columns:1fr}footer{display:grid;gap:7px}}`;

const js = `const $=id=>document.getElementById(id);let markets=[],selected='BTCUSD',side='long',pending=null;const money=v=>Number(v).toLocaleString(undefined,{style:'currency',currency:'USD',maximumFractionDigits:2});const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(path,init){const r=await fetch(path,init);const b=await r.json();if(!r.ok)throw new Error(b.error?.message||b.message||'Request failed');return b}function body(token=false){const b={market:selected,side,sizeUsd:$('size').value,leverage:$('leverage').value,orderType:$('order-type').value};if(b.orderType==='limit')b.limitPrice=$('limit-price').value;if($('take-profit').value)b.takeProfitPrice=$('take-profit').value;if($('stop-loss').value)b.stopLossPrice=$('stop-loss').value;if($('trailing-stop').value)b.trailingStopPercent=$('trailing-stop').value;if(token)b.confirmationToken=pending.confirmationToken;return b}function clearPreview(){$('preview').hidden=true;pending=null;$('stage').textContent='1 · CONFIGURE'}function setSide(v){side=v;$('long').className=v==='long'?'active long':'long';$('short').className=v==='short'?'active':'';clearPreview()}async function health(){try{const h=await api('/health');$('connection-dot').className='ok';$('connection-text').textContent='SERVICE HEALTHY';$('mode').textContent=h.liveTradingEnabled||h.perps?.liveExecutionEnabled?'UNSAFE':'PAPER ONLY';$('mode').className=h.liveTradingEnabled||h.perps?.liveExecutionEnabled?'negative':'positive'}catch(e){$('connection-text').textContent='SERVICE OFFLINE';$('mode').textContent='OFFLINE'}}async function loadMarkets(){const b=await api('/api/perps/markets');markets=b.markets;selected=markets.some(m=>m.symbol===selected)?selected:markets[0]?.symbol;$('markets').innerHTML=markets.map(m=>'<button data-symbol="'+esc(m.symbol)+'" class="'+(m.symbol===selected?'active':'')+'">'+esc(m.baseAsset)+'</button>').join('');$('markets').querySelectorAll('button').forEach(x=>x.onclick=()=>{selected=x.dataset.symbol;clearPreview();renderMarket()});renderMarket()}function renderMarket(){const m=markets.find(x=>x.symbol===selected);if(!m)return;$('symbol').textContent=m.symbol;$('price').textContent=money(m.referencePrice);$('leverage').max=Number(m.maxLeverage);$('markets').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x.dataset.symbol===selected))}async function loadAccount(){const a=await api('/api/perps/account');$('equity').textContent=money(a.equity);$('available').textContent=money(a.availableMargin);$('used').textContent=money(a.usedMargin);$('pnl').textContent=money(a.unrealizedPnl);$('pnl').className=Number(a.unrealizedPnl)>=0?'positive':'negative'}async function loadPositions(){const b=await api('/api/perps/positions');$('positions').innerHTML=b.positions.length?'<table class="data-table"><thead><tr><th>MARKET</th><th>SIDE</th><th>SIZE</th><th>ENTRY</th><th>MARK</th><th>LEVERAGE</th><th>UNREALIZED P&L</th><th></th></tr></thead><tbody>'+b.positions.map(p=>'<tr><td><b>'+esc(p.market)+'</b></td><td class="'+(p.side==='long'?'positive':'negative')+'">'+esc(p.side.toUpperCase())+'</td><td>'+money(p.sizeUsd)+'</td><td>'+money(p.entryPrice)+'</td><td>'+money(p.markPrice)+'</td><td>'+esc(p.leverage)+'×</td><td class="'+(Number(p.unrealizedPnl)>=0?'positive':'negative')+'">'+money(p.unrealizedPnl)+'</td><td><button data-close="'+esc(p.market)+'">Close</button></td></tr>').join('')+'</tbody></table>':'<p class="empty">No open paper positions.</p>';$('positions').querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>closePosition(x.dataset.close))}async function loadOrders(){const b=await api('/api/perps/orders');$('orders').innerHTML=b.orders.length?'<table class="data-table"><thead><tr><th>TIME</th><th>MARKET</th><th>SIDE</th><th>TYPE</th><th>SIZE</th><th>PRICE</th><th>STATUS</th></tr></thead><tbody>'+b.orders.slice().reverse().map(o=>'<tr><td>'+new Date(o.createdAt).toLocaleString()+'</td><td><b>'+esc(o.market)+'</b></td><td class="'+(o.side==='long'?'positive':'negative')+'">'+esc(o.side.toUpperCase())+'</td><td>'+esc(o.orderType.toUpperCase())+'</td><td>'+money(o.notionalUsd||o.sizeUsd)+'</td><td>'+money(o.fillPrice||o.limitPrice||o.referencePrice)+'</td><td>'+esc(o.status.toUpperCase())+'</td></tr>').join('')+'</tbody></table>':'<p class="empty">No paper orders yet.</p>'}async function refresh(){await Promise.all([loadAccount(),loadPositions(),loadOrders()])}async function closePosition(m){if(!confirm('Close the entire '+m+' paper position?'))return;try{await api('/api/perps/positions/'+encodeURIComponent(m)+'/close',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({percentage:'100'})});await refresh()}catch(e){alert(e.message)}}$('long').onclick=()=>setSide('long');$('short').onclick=()=>setSide('short');$('refresh').onclick=refresh;$('leverage').oninput=()=>{$('leverage-label').textContent=$('leverage').value+'×';clearPreview()};$('order-type').onchange=()=>{$('limit-wrap').hidden=$('order-type').value!=='limit';clearPreview()};['size','limit-price','take-profit','stop-loss','trailing-stop'].forEach(id=>$(id).oninput=clearPreview);$('order-form').onsubmit=async e=>{e.preventDefault();const button=$('preview-button');button.disabled=true;$('feedback').className='feedback loading';$('feedback').textContent='Calculating paper margin and risk…';try{const b=await api('/api/perps/orders/preview',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body())});pending=b.preview;$('entry').textContent=money(pending.estimatedEntryPrice);$('margin').textContent=money(pending.initialMarginUsd);$('fee').textContent=money(pending.estimatedFeeUsd);$('liquidation').textContent=money(pending.liquidationPrice);$('preview').hidden=false;$('stage').textContent='2 · CONFIRM';$('feedback').className='feedback';$('feedback').textContent='Preview ready. Review every value before confirming the paper order.'}catch(err){$('feedback').className='feedback error';$('feedback').textContent=err.message;clearPreview()}finally{button.disabled=false}};$('confirm').onclick=async()=>{if(!pending)return;const button=$('confirm');button.disabled=true;try{await api('/api/perps/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body(true))});$('feedback').className='feedback';$('feedback').textContent='Paper order filled. No live venue transaction was submitted.';clearPreview();await refresh()}catch(e){$('feedback').className='feedback error';$('feedback').textContent=e.message}finally{button.disabled=false}};Promise.all([health(),loadMarkets(),refresh()]).catch(e=>{$('feedback').className='feedback error';$('feedback').textContent=e.message});setInterval(()=>{health();refresh()},20000);`;

const trackingCss = `.notice strong{margin-left:0}.feed-state{margin-left:auto;display:grid;grid-template-columns:auto auto;align-items:center;gap:2px 8px;text-align:right}.feed-state i{grid-row:1/3;width:8px;height:8px;border-radius:50%;background:var(--amber)}.feed-state i.ok{background:var(--green);box-shadow:0 0 12px var(--green)}.feed-state i.stale{background:var(--red)}.feed-state small{color:var(--muted);font-size:9px}.flash-up{animation:flashUp .8s ease}.flash-down{animation:flashDown .8s ease}@keyframes flashUp{0%{color:var(--green);text-shadow:0 0 18px var(--green)}100%{text-shadow:none}}@keyframes flashDown{0%{color:var(--red);text-shadow:0 0 18px var(--red)}100%{text-shadow:none}}.section-note{color:var(--muted);font-size:11px;margin:-10px 0 14px}.trigger{font:10px ui-monospace,monospace;white-space:nowrap}.status-pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 7px;font:9px ui-monospace,monospace;letter-spacing:.06em}.status-pill.closed,.status-pill.filled{border-color:#32d49a66;color:var(--green)}.status-pill.triggered{border-color:#f5a62377;color:var(--amber)}.status-pill.cancelled,.status-pill.rejected{border-color:#ff607866;color:var(--red)}@media(max-width:560px){.feed-state strong{font-size:8px}.feed-state small{display:block!important}}`;

const trackingJs = `const $=id=>document.getElementById(id);let markets=[],selected='BTCUSD',side='long',pending=null,polling=false,lastPrices={},lastPnl={},lastMarks={};const money=v=>Number(v).toLocaleString(undefined,{style:'currency',currency:'USD',maximumFractionDigits:2});const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const val=(o,...keys)=>keys.map(k=>o?.[k]).find(v=>v!==undefined&&v!==null);async function api(path,init){const r=await fetch(path,init);const b=await r.json();if(!r.ok)throw new Error(b.error?.message||b.message||'Request failed');return b}function flash(el,next,previous){el.classList.remove('flash-up','flash-down');if(previous!==undefined&&Number(next)!==Number(previous)){void el.offsetWidth;el.classList.add(Number(next)>Number(previous)?'flash-up':'flash-down')}}function body(token=false){const b={market:selected,side,sizeUsd:$('size').value,leverage:$('leverage').value,orderType:$('order-type').value};if(b.orderType==='limit')b.limitPrice=$('limit-price').value;if($('take-profit').value)b.takeProfitPrice=$('take-profit').value;if($('stop-loss').value)b.stopLossPrice=$('stop-loss').value;if($('trailing-stop').value)b.trailingStopPercent=$('trailing-stop').value;if(token)b.confirmationToken=pending.confirmationToken;return b}function clearPreview(){$('preview').hidden=true;pending=null;$('stage').textContent='1 · CONFIGURE'}function setSide(v){side=v;$('long').className=v==='long'?'active long':'long';$('short').className=v==='short'?'active':'';clearPreview()}function setFeed(ok,updated,source){$('feed-dot').className=ok?'ok':'stale';$('feed-status').textContent=ok?'REFERENCE FEED LIVE':'REFERENCE FEED STALE';$('feed-updated').textContent='Last update '+(updated?new Date(updated).toLocaleTimeString():'—');$('price-source').textContent=(source?String(source).toUpperCase()+' · ':'BINANCE USD-M · ')+'PROTECTED RISK ENGINE'}async function health(){try{const h=await api('/health');$('connection-dot').className='ok';$('connection-text').textContent='SERVICE HEALTHY';$('mode').textContent=h.liveTradingEnabled||h.perps?.liveExecutionEnabled?'LIVE READY':'SAFE TESTING';$('mode').className=h.liveTradingEnabled||h.perps?.liveExecutionEnabled?'negative':'positive'}catch(e){$('connection-dot').className='';$('connection-text').textContent='SERVICE OFFLINE';$('mode').textContent='OFFLINE';setFeed(false)}}async function loadMarkets(first=false){const b=await api('/api/perps/markets');const next=b.markets||[];const updated=val(b,'updatedAt','asOf','timestamp')||val(next[0],'updatedAt','asOf','timestamp')||new Date().toISOString();const source=val(b,'source','feedSource')||val(next[0],'source','feedSource');if(first||!markets.length){markets=next;selected=markets.some(m=>m.symbol===selected)?selected:markets[0]?.symbol;$('markets').innerHTML=markets.map(m=>'<button data-symbol="'+esc(m.symbol)+'" class="'+(m.symbol===selected?'active':'')+'">'+esc(m.baseAsset)+'</button>').join('');$('markets').querySelectorAll('button').forEach(x=>x.onclick=()=>{selected=x.dataset.symbol;clearPreview();renderMarket()})}else markets=next;renderMarket();setFeed(true,updated,source)}function renderMarket(){const m=markets.find(x=>x.symbol===selected);if(!m)return;const price=val(m,'markPrice','referencePrice','price');$('symbol').textContent=m.symbol;flash($('price'),price,lastPrices[selected]);$('price').textContent=money(price);lastPrices[selected]=price;$('leverage').max=Number(m.maxLeverage);$('markets').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x.dataset.symbol===selected))}async function loadAccount(){const a=await api('/api/perps/account');if($('wallet-balance')){if(a.walletBnbBalance)$('wallet-balance').textContent=a.walletBnbBalance+' BNB';else if(a.balance)$('wallet-balance').textContent=money(a.balance);}$('equity').textContent=money(a.equity);$('available').textContent=money(a.availableMargin);$('used').textContent=money(a.usedMargin);flash($('pnl'),a.unrealizedPnl,lastPnl.account);$('pnl').textContent=money(a.unrealizedPnl);$('pnl').className=Number(a.unrealizedPnl)>=0?'positive':'negative';lastPnl.account=a.unrealizedPnl}function triggerText(p){const tp=val(p,'takeProfitPrice','takeProfit'),sl=val(p,'stopLossPrice','stopLoss'),trail=val(p,'trailingStopPercent'),trigger=val(p,'trailingTriggerPrice');return '<span class="trigger">TP '+(tp?money(tp):'—')+'<br>SL '+(sl?money(sl):'—')+'<br>TRAIL '+(trail?esc(trail)+'% @ '+(trigger?money(trigger):'waiting'):'—')+'</span>'}async function loadPositions(){const b=await api('/api/perps/positions'),rows=b.positions||[];$('positions').innerHTML=rows.length?'<table class="data-table"><thead><tr><th>MARKET</th><th>SIDE</th><th>SIZE</th><th>ENTRY</th><th>LIVE MARK</th><th>TP / SL / TRAIL</th><th>LEVERAGE</th><th>UNREALIZED P&L</th><th></th></tr></thead><tbody>'+rows.map(p=>{const pnl=val(p,'unrealizedPnl','unrealizedPnlUsd')||0,mark=val(p,'markPrice','referencePrice');const changed=lastPnl[p.market]!==undefined&&Number(lastPnl[p.market])!==Number(pnl),previousMark=lastMarks[p.market],markDirection=previousMark===undefined?"":Number(mark)>Number(previousMark)?"flash-up positive":Number(mark)<Number(previousMark)?"flash-down negative":"";lastPnl[p.market]=pnl;lastMarks[p.market]=mark;return '<tr><td><b>'+esc(p.market)+'</b></td><td class="'+(p.side==='long'?'positive':'negative')+'">'+esc(p.side.toUpperCase())+'</td><td>'+money(val(p,'sizeUsd','notionalUsd'))+'</td><td>'+money(p.entryPrice)+'</td><td class="'+markDirection+'">'+money(mark)+'</td><td>'+triggerText(p)+'</td><td>'+esc(p.leverage)+'×</td><td class="'+(Number(pnl)>=0?'positive':'negative')+(changed?' flash-'+(Number(pnl)>=0?'up':'down'):'')+'">'+money(pnl)+'</td><td><button data-close="'+esc(p.market)+'">Close</button></td></tr>'}).join('')+'</tbody></table>':'<p class="empty">No open positions.</p>';$('positions').querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>closePosition(x.dataset.close))}function reason(o){return val(o,'closeReason','triggerReason','reason','statusReason')||'—'}async function loadOrders(){const b=await api('/api/perps/orders'),rows=b.orders||[];$('orders').innerHTML=rows.length?'<table class="data-table"><thead><tr><th>TIME</th><th>MARKET</th><th>SIDE</th><th>TYPE</th><th>SIZE</th><th>PRICE</th><th>TP / SL / TRAIL</th><th>STATUS</th><th>RESULT</th></tr></thead><tbody>'+rows.slice().reverse().map(o=>{const status=String(o.status||'unknown').toLowerCase();return '<tr><td>'+new Date(val(o,'updatedAt','closedAt','filledAt','createdAt')).toLocaleString()+'</td><td><b>'+esc(o.market)+'</b></td><td class="'+(o.side==='long'?'positive':'negative')+'">'+esc(String(o.side||'').toUpperCase())+'</td><td>'+esc(String(o.orderType||o.type||'').toUpperCase())+'</td><td>'+money(val(o,'notionalUsd','sizeUsd'))+'</td><td>'+money(val(o,'exitPrice','fillPrice','limitPrice','referencePrice'))+'</td><td>'+triggerText(o)+'</td><td><span class="status-pill '+esc(status)+'">'+esc(status.toUpperCase())+'</span></td><td>'+esc(reason(o))+'</td></tr>'}).join('')+'</tbody></table>':'<p class="empty">No orders logged yet.</p>'}async function refresh(){if(polling)return;polling=true;try{await Promise.all([loadMarkets(),loadAccount(),loadPositions(),loadOrders()]);setFeed(true,new Date().toISOString())}catch(e){setFeed(false);throw e}finally{polling=false}}async function closePosition(m){if(!confirm('Close the '+m+' position?'))return;try{await api('/api/perps/positions/'+encodeURIComponent(m)+'/close',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({percentage:'100'})});await refresh()}catch(e){alert(e.message)}}$('long').onclick=()=>setSide('long');$('short').onclick=()=>setSide('short');$('refresh').onclick=()=>refresh().catch(()=>{});$('leverage').oninput=()=>{$('leverage-label').textContent=$('leverage').value+'×';clearPreview()};$('order-type').onchange=()=>{$('limit-wrap').hidden=$('order-type').value!=='limit';clearPreview()};['size','limit-price','take-profit','stop-loss','trailing-stop'].forEach(id=>$(id).oninput=clearPreview);$('order-form').onsubmit=async e=>{e.preventDefault();const button=$('preview-button');button.disabled=true;$('feedback').className='feedback loading';$('feedback').textContent='Validating margin and risk boundaries…';try{const b=await api('/api/perps/orders/preview',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body())});pending=b.preview;$('entry').textContent=money(pending.estimatedEntryPrice);$('margin').textContent=money(pending.initialMarginUsd);$('fee').textContent=money(pending.estimatedFeeUsd);$('liquidation').textContent=money(pending.liquidationPrice);$('preview').hidden=false;$('stage').textContent='2 · CONFIRM';$('feedback').className='feedback';$('feedback').textContent='Preview ready. Review order parameters before confirming.'}catch(err){$('feedback').className='feedback error';$('feedback').textContent=err.message;clearPreview()}finally{button.disabled=false}};$('confirm').onclick=async()=>{if(!pending)return;const button=$('confirm');button.disabled=true;try{await api('/api/perps/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body(true))});$('feedback').className='feedback';$('feedback').textContent='Order filled safely. Position updated.';clearPreview();await refresh()}catch(e){$('feedback').className='feedback error';$('feedback').textContent=e.message}finally{button.disabled=false}};Promise.all([health(),loadMarkets(true),refresh()]).catch(e=>{$('feedback').className='feedback error';$('feedback').textContent=e.message});setInterval(()=>{health();refresh().catch(()=>{})},2000);`;

