const comparisonJs = `async function loadSpcxModel(){try{const data=await api('/api/research/spcx-btc'),host=$('spcx-chart'),points=data.points,events=data.events;if(!points.length)throw new Error('No comparison data');const W=1100,H=360,M={l:52,r:22,t:30,b:42},min=Math.min(...points.flatMap(p=>[p.spcxIndexed,p.btcIndexed])),max=Math.max(...points.flatMap(p=>[p.spcxIndexed,p.btcIndexed])),start=Date.parse(points[0].date),end=Date.parse(points.at(-1).date),x=d=>M.l+(Date.parse(d)-start)/(end-start)*(W-M.l-M.r),y=v=>M.t+(max-v)/(max-min)*(H-M.t-M.b),path=key=>points.map((p,i)=>(i?'L':'M')+x(p.date).toFixed(1)+' '+y(p[key]).toFixed(1)).join(' '),ticks=[min,(min+max)/2,max];host.innerHTML='<div class="chart-legend"><span><i style="background:#f5a623"></i>SPCX</span><span><i style="background:#d7ff62"></i>BTC</span></div><svg viewBox="0 0 '+W+' '+H+'" role="img"><title>SPCX and Bitcoin indexed performance with shareholder unlock dates</title>'+ticks.map(v=>'<line class="chart-grid" x1="'+M.l+'" x2="'+(W-M.r)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text class="chart-axis" x="4" y="'+(y(v)+4)+'">'+v.toFixed(0)+'</text>').join('')+events.filter(e=>e.point&&Date.parse(e.date)<=end).map(e=>'<line class="chart-event '+e.status+'" x1="'+x(e.point.date)+'" x2="'+x(e.point.date)+'" y1="'+M.t+'" y2="'+(H-M.b)+'"/><text class="chart-label" x="'+(x(e.point.date)+4)+'" y="'+(M.t+12)+'">'+e.date.slice(5)+'</text>').join('')+'<path class="chart-spcx" d="'+path('spcxIndexed')+'"/><path class="chart-btc" d="'+path('btcIndexed')+'"/>'+events.filter(e=>e.point&&Date.parse(e.date)<=end).map(e=>'<circle class="chart-dot-spcx" cx="'+x(e.point.date)+'" cy="'+y(e.point.spcxIndexed)+'" r="4"/><circle class="chart-dot-btc" cx="'+x(e.point.date)+'" cy="'+y(e.point.btcIndexed)+'" r="4"/>').join('')+'<text class="chart-axis" x="'+M.l+'" y="'+(H-10)+'">'+points[0].date+'</text><text class="chart-axis" text-anchor="end" x="'+(W-M.r)+'" y="'+(H-10)+'">'+points.at(-1).date+'</text></svg>';$('spcx-events').innerHTML=events.map(e=>'<article><time>'+esc(e.date)+'</time><b>'+esc(e.label)+'</b><span>'+esc(e.release)+(e.point?' · SPCX '+e.point.spcxIndexed.toFixed(1)+' / BTC '+e.point.btcIndexed.toFixed(1):' · scheduled')+'</span></article>').join('');$('spcx-method').textContent=data.methodology+' Sources: SEC prospectus schedule; Yahoo Finance daily closes.'}catch(e){$('spcx-method').textContent='SPCX/BTC model unavailable: '+e.message}}loadSpcxModel();`;
const orderGuidanceJs = `function updateOrderGuidance(){const market=markets.find(m=>m.symbol===selected),price=Number(val(market,'markPrice','referencePrice','price'));if(!Number.isFinite(price)||price<=0)return;const tp=side==='long'?price*1.01:price*.99,sl=side==='long'?price*.99:price*1.01;$('take-profit').placeholder=tp.toFixed(2);$('stop-loss').placeholder=sl.toFixed(2);$('take-profit-help').textContent=side==='long'?'For a long, enter a coin price above '+money(price)+'. Example: '+money(tp):'For a short, enter a coin price below '+money(price)+'. Example: '+money(tp);$('stop-loss-help').textContent=side==='long'?'For a long, enter a coin price below '+money(price)+'. Example: '+money(sl):'For a short, enter a coin price above '+money(price)+'. Example: '+money(sl)}const renderMarketWithGuidance=renderMarket;renderMarket=function(){renderMarketWithGuidance();updateOrderGuidance()};$('long').addEventListener('click',updateOrderGuidance);$('short').addEventListener('click',updateOrderGuidance);updateOrderGuidance();`;

