const marketHeroJs = `let currentTf='LIVE',activeChartMode='line',cachedInsight=null;const svgEl=id=>document.getElementById(id);async function loadInsights(symbol,tf){try{const s=symbol||selected||'BTCUSD',t=tf||currentTf||'LIVE';const data=await api('/api/perps/insights?symbol='+encodeURIComponent(s)+'&timeframe='+encodeURIComponent(t));cachedInsight=data;const base=data.baseAsset||s.replace(/USD[T]?$/,'');if($('hero-asset-icon'))$('hero-asset-icon').textContent=base==='BTC'?'₿':base==='ETH'?'Ξ':'BNB';if($('hero-asset-symbol'))$('hero-asset-symbol').textContent=base;if($('hero-leverage-tag'))$('hero-leverage-tag').textContent=data.maxLeverage||'3.0x';if($('hero-price'))$('hero-price').textContent=data.markPrice;if($('hero-change')){$('hero-change').textContent=(data.isPositive?'▲ ':'▼ ')+data.priceChange24h+' ('+data.priceChangePercent24h+')';$('hero-change').className='hero-change '+(data.isPositive?'positive':'negative')}if($('hero-vol-24h'))$('hero-vol-24h').textContent=data.volume24h;if($('hero-oi'))$('hero-oi').textContent=data.openInterest;if($('hero-funding-tag'))$('hero-funding-tag').textContent=data.fundingRate;drawHeroChart(data.points,data.markPrice);if($('order-up-pct'))$('order-up-pct').textContent=data.orderData.buyPercent+'% Up';if($('order-down-pct'))$('order-down-pct').textContent=data.orderData.sellPercent+'% Down';if($('order-bar-green'))$('order-bar-green').style.width=data.orderData.buyPercent+'%';if($('order-bar-red'))$('order-bar-red').style.width=data.orderData.sellPercent+'%';if($('card-vol-24h'))$('card-vol-24h').textContent=data.orderData.volume24h;if($('card-oi'))$('card-oi').textContent=data.orderData.openInterest;if($('card-funding'))$('card-funding').innerHTML=data.orderData.fundingRate+' <small>in '+esc(data.fundingCountdown)+'</small>';if($('card-max-lev'))$('card-max-lev').textContent=data.orderData.maxLeverage;if($('prediction-question'))$('prediction-question').textContent='Odds '+base+' closes higher today';if($('pred-up-pct'))$('pred-up-pct').textContent=data.predictionData.upPercent+'% Up';if($('pred-down-pct'))$('pred-down-pct').textContent=data.predictionData.downPercent+'% Down';if($('pred-bar-green'))$('pred-bar-green').style.width=data.predictionData.upPercent+'%';if($('pred-bar-red'))$('pred-bar-red').style.width=data.predictionData.downPercent+'%';if($('forecast-daily'))$('forecast-daily').textContent=data.predictionData.dailyForecast;if($('forecast-week'))$('forecast-week').textContent=data.predictionData.weekForecast;if($('forecast-month'))$('forecast-month').textContent=data.predictionData.monthForecast;if($('forecast-year'))$('forecast-year').textContent=data.predictionData.yearForecast;if($('flow-stream')&&data.recentFlow){$('flow-stream').innerHTML=data.recentFlow.map(f=>'<span class=\"flow-bubble '+(f.isBuy?'buy':'sell')+'\">'+esc(f.amount)+'</span>').join('')}}catch(e){console.error('Insights error:',e)}}function drawHeroChart(points,markPriceStr){if(!points||!points.length||!svgEl('hero-svg-chart'))return;const W=1000,H=350,padT=25,padB=35,padL=10,padR=85;const prices=points.map(p=>p.price);let min=Math.min(...prices),max=Math.max(...prices);if(min===max){min*=.998;max*=1.002}const range=max-min,pad=range*.08;min-=pad;max+=pad;const getX=i=>padL+(i/(points.length-1))*(W-padL-padR),getY=v=>padT+(1-(v-min)/(max-min))*(H-padT-padB);const gridGroup=svgEl('chart-grid');if(gridGroup){const ticks=[min+(max-min)*.15,min+(max-min)*.45,min+(max-min)*.75,max-(max-min)*.05];gridGroup.innerHTML=ticks.map(t=>{const y=getY(t).toFixed(1);return '<line class=\"chart-grid-line\" x1=\"'+padL+'\" x2=\"'+(W-padR+5)+'\" y1=\"'+y+'\" y2=\"'+y+'\"/><text class=\"chart-grid-text\" x=\"'+(W-padR+10)+'\" y=\"'+(parseFloat(y)+3)+'\">$'+t.toFixed(0)+'</text>'}).join('')}const coords=points.map((p,i)=>({x:getX(i),y:getY(p.price),p}));if(activeChartMode==='candles'){const candleWidth=Math.max(3,Math.min(10,((W-padL-padR)/points.length)*.65));let candlesSvg='';points.forEach((p,i)=>{const x=getX(i),isUp=p.close>=p.open,col=isUp?'#32d49a':'#ff6078',highY=getY(p.high),lowY=getY(p.low),openY=getY(p.open),closeY=getY(p.close),bodyTop=Math.min(openY,closeY),bodyHeight=Math.max(2,Math.abs(closeY-openY));candlesSvg+='<line x1=\"'+x.toFixed(1)+'\" x2=\"'+x.toFixed(1)+'\" y1=\"'+highY.toFixed(1)+'\" y2=\"'+lowY.toFixed(1)+'\" stroke=\"'+col+'\" stroke-width=\"1\"/><rect x=\"'+(x-candleWidth/2).toFixed(1)+'\" y=\"'+bodyTop.toFixed(1)+'\" width=\"'+candleWidth.toFixed(1)+'\" height=\"'+bodyHeight.toFixed(1)+'\" fill=\"'+col+'\"/>'});gridGroup.innerHTML+='<g id=\"candle-items\">'+candlesSvg+'</g>';svgEl('chart-stroke').setAttribute('d','');svgEl('chart-area').setAttribute('d','')}else{const lineD=coords.map((c,i)=>(i===0?'M':'L')+c.x.toFixed(1)+' '+c.y.toFixed(1)).join(' '),baselineY=H-padB,areaD=lineD+' L '+coords[coords.length-1].x.toFixed(1)+' '+baselineY+' L '+coords[0].x.toFixed(1)+' '+baselineY+' Z';svgEl('chart-stroke').setAttribute('d',lineD);svgEl('chart-area').setAttribute('d',areaD)}const lastCoord=coords[coords.length-1],curLine=svgEl('current-price-line');if(curLine){curLine.setAttribute('x1','0');curLine.setAttribute('x2',String(W-padR+5));curLine.setAttribute('y1',lastCoord.y.toFixed(1));curLine.setAttribute('y2',lastCoord.y.toFixed(1))}const badgeBg=svgEl('badge-bg'),badgeText=svgEl('badge-text');if(badgeBg&&badgeText){const badgeX=W-padR+8,badgeY=lastCoord.y-10;badgeBg.setAttribute('x',String(badgeX));badgeBg.setAttribute('y',badgeY.toFixed(1));badgeText.setAttribute('x',String(badgeX+37));badgeText.setAttribute('y',(badgeY+14).toFixed(1));badgeText.textContent=money(points[points.length-1].price)}const chartViewport=$('chart-viewport');if(chartViewport&&!chartViewport._hasEvents){chartViewport._hasEvents=true;const crosshair=svgEl('chart-crosshair'),vLine=svgEl('crosshair-v'),hLine=svgEl('crosshair-h'),dot=svgEl('crosshair-dot'),timeBg=svgEl('crosshair-label-bg'),timeText=svgEl('crosshair-time-text');function onMove(e){if(!cachedInsight||!cachedInsight.points||!cachedInsight.points.length)return;const rect=chartViewport.getBoundingClientRect(),clientX=e.touches?e.touches[0].clientX:e.clientX,relX=(clientX-rect.left)/rect.width,svgX=relX*W,idx=Math.max(0,Math.min(coords.length-1,Math.round((svgX-padL)/((W-padL-padR)/(coords.length-1))))),target=coords[idx];if(!target)return;if(crosshair)crosshair.style.display='inline';if(vLine){vLine.setAttribute('x1',target.x.toFixed(1));vLine.setAttribute('x2',target.x.toFixed(1))}if(hLine){hLine.setAttribute('y1',target.y.toFixed(1));hLine.setAttribute('y2',target.y.toFixed(1));hLine.setAttribute('x2',String(W-padR))}if(dot){dot.setAttribute('cx',target.x.toFixed(1));dot.setAttribute('cy',target.y.toFixed(1))}if(timeBg&&timeText){const bgX=Math.max(10,Math.min(W-padR-70,target.x-38));timeBg.setAttribute('x',bgX.toFixed(1));timeText.setAttribute('x',(bgX+38).toFixed(1));timeText.textContent=target.p.timeLabel||''}if($('hero-price'))$('hero-price').textContent=money(target.p.price)}function onLeave(){if(crosshair)crosshair.style.display='none';if(cachedInsight&&$('hero-price'))$('hero-price').textContent=cachedInsight.markPrice}chartViewport.addEventListener('mousemove',onMove);chartViewport.addEventListener('touchmove',onMove,{passive:true});chartViewport.addEventListener('mouseleave',onLeave);chartViewport.addEventListener('touchend',onLeave)}}function initInsightEvents(){const tfContainer=$('timeframe-selector');if(tfContainer){tfContainer.querySelectorAll('button').forEach(btn=>{btn.onclick=()=>{tfContainer.querySelectorAll('button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');currentTf=btn.dataset.tf;loadInsights(selected,currentTf)}})}const modeLine=$('chart-mode-line'),modeCandles=$('chart-mode-candles');if(modeLine&&modeCandles){modeLine.onclick=()=>{modeLine.classList.add('active');modeCandles.classList.remove('active');activeChartMode='line';if(cachedInsight)drawHeroChart(cachedInsight.points,cachedInsight.markPrice)};modeCandles.onclick=()=>{modeCandles.classList.add('active');modeLine.classList.remove('active');activeChartMode='candles';if(cachedInsight)drawHeroChart(cachedInsight.points,cachedInsight.markPrice)}}}const prevRenderMarket=renderMarket;renderMarket=function(){prevRenderMarket();loadInsights(selected,currentTf)};loadInsights(selected,currentTf);initInsightEvents();setInterval(()=>{loadInsights(selected,currentTf)},3500);`;

const modeAndAuthCss = `.mode-switch-wrap{display:flex;align-items:center}.mode-toggle-pill{display:flex;background:#080c14;border:1px solid #1e2638;border-radius:999px;padding:3px;gap:2px}.mode-toggle-pill button{border:0;background:transparent;color:#6b7280;padding:6px 13px;border-radius:999px;font:700 11px ui-monospace,monospace;cursor:pointer;transition:all .18s}.mode-toggle-pill button.active.safe{background:#32d49a18;color:#32d49a;box-shadow:0 0 10px #32d49a22}.mode-toggle-pill button.active.live{background:#ff607822;color:#ff6078;box-shadow:0 0 12px #ff607833}.auth-pill-btn{border:1px solid #283247;background:#111624;color:#f4f6fb;padding:7px 14px;border-radius:999px;font:600 11px ui-monospace,monospace;cursor:pointer;transition:all .15s}.auth-pill-btn:hover{border-color:#f5a623;color:#f5a623}.cido-dialog{border:0;border-radius:14px;padding:0;background:transparent;max-width:480px;width:90%;color:#f4f6fb;box-shadow:0 20px 45px rgba(0,0,0,0.85)}.cido-dialog::backdrop{background:rgba(5,8,15,0.78);backdrop-filter:blur(6px)}.dialog-card{background:#0c111c;border:1px solid #202b3d;border-radius:14px;padding:24px;display:flex;flex-direction:column;gap:16px}.dialog-header{display:flex;justify-content:space-between;align-items:center}.dialog-header h3{margin:0;font-size:17px;font-weight:700;letter-spacing:.02em}.dialog-header.warning h3{color:#f5a623}.close-x{background:transparent;border:0;color:#6b7280;font-size:16px;cursor:pointer}.close-x:hover{color:#fff}.dialog-body p{margin:0 0 12px;font-size:13px;color:#8d98ae;line-height:1.5}.dialog-body strong{color:#f4f6fb}.dialog-rules{display:flex;flex-direction:column;gap:8px;border:1px solid #1a2333;border-radius:8px;padding:12px;background:#070a10}.dialog-rules div{display:flex;justify-content:space-between;font-size:11px;gap:12px}.dialog-rules b{color:#f5a623;font:10px ui-monospace,monospace}.dialog-rules span{color:#8d98ae;text-align:right}.dialog-note{font:10px ui-monospace,monospace;color:#6b7280;margin-top:8px}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:12px}.ghost-btn{border:1px solid #283247;background:transparent;color:#8d98ae;padding:9px 14px;border-radius:7px;cursor:pointer;font:600 12px inherit}.warning-btn{border:0;background:#f5a623;color:#000;padding:9px 16px;border-radius:7px;font:700 12px inherit;cursor:pointer}.auth-tabs{display:flex;gap:8px;border-bottom:1px solid #1a2333;padding-bottom:12px;margin-bottom:14px}.auth-tabs button{background:transparent;border:0;color:#6b7280;font:700 12px ui-monospace,monospace;padding:6px 12px;cursor:pointer}.auth-tabs button.active{color:#f4f6fb;border-bottom:2px solid #f5a623}.auth-submit{width:100%;margin-top:12px}.auth-feedback{font:11px ui-monospace,monospace;padding:8px 10px;border-radius:5px;background:#ff607814;color:#ff9bab;border:1px solid #ff607833;margin-top:8px}`;

const modeAndAuthJs = `let tradingMode='safe',currentUser=null;function updateModeUI(){const isLive=tradingMode==='live';$('btn-mode-live').classList.toggle('active',isLive);$('btn-mode-safe').classList.toggle('active',!isLive);if($('mode')){$('mode').textContent=isLive?'LIVE READY':'SAFE TESTING';$('mode').className=isLive?'negative':'positive'}if($('preview-button')){$('preview-button').textContent=isLive?'Preview LIVE order':'Preview order';$('preview-button').style.background=isLive?'#f5a623':''}}$('btn-mode-live').onclick=()=>{if(tradingMode==='safe')$('live-confirm-modal').showModal()};$('btn-mode-safe').onclick=()=>{tradingMode='safe';updateModeUI()};$('close-live-modal').onclick=()=>$('live-confirm-modal').close();$('cancel-live-btn').onclick=()=>$('live-confirm-modal').close();$('confirm-live-btn').onclick=()=>{tradingMode='live';updateModeUI();$('live-confirm-modal').close()};let authMode='signin';$('tab-signin').onclick=()=>{authMode='signin';$('tab-signin').classList.add('active');$('tab-signup').classList.remove('active');$('auth-title').textContent='Account Sign In';$('auth-submit-btn').textContent='Sign In'};$('tab-signup').onclick=()=>{authMode='signup';$('tab-signup').classList.add('active');$('tab-signin').classList.remove('active');$('auth-title').textContent='Create Account';$('auth-submit-btn').textContent='Sign Up'};$('close-auth-modal').onclick=()=>$('auth-modal').close();$('auth-header-btn').onclick=()=>{if(currentUser){if(confirm('Sign out of '+currentUser.email+'?')){localStorage.removeItem('cido_auth_token');currentUser=null;$('auth-header-btn').textContent='Sign In'}}else{$('auth-modal').showModal()}};async function checkAuthSession(){const token=localStorage.getItem('cido_auth_token');if(!token)return;try{const res=await fetch('/api/auth/me',{headers:{'Authorization':'Bearer '+token}});if(res.ok){const data=await res.json();if(data.authenticated&&data.user){currentUser=data.user;$('auth-header-btn').textContent=currentUser.email?currentUser.email.split('@')[0]:'Profile'}}}catch{}}$('auth-form').onsubmit=async(e)=>{e.preventDefault();const email=$('auth-email').value,password=$('auth-password').value,fb=$('auth-feedback');fb.hidden=false;fb.textContent='Authenticating…';try{const cfgRes=await fetch('/api/auth/config');const cfg=await cfgRes.json();if(!cfg.enabled){currentUser={email,id:'local-user'};localStorage.setItem('cido_auth_token','local-demo-token');$('auth-header-btn').textContent=email.split('@')[0];$('auth-modal').close();return}const {createClient}=window.supabase||{};if(createClient&&cfg.supabaseUrl&&cfg.supabaseAnonKey){const client=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);const {data,error}=authMode==='signup'?await client.auth.signUp({email,password}):await client.auth.signInWithPassword({email,password});if(error)throw error;const token=data.session?.access_token;if(token){localStorage.setItem('cido_auth_token',token);currentUser=data.user;$('auth-header-btn').textContent=email.split('@')[0];$('auth-modal').close()}}else{currentUser={email,id:'local-user'};localStorage.setItem('cido_auth_token','local-demo-token');$('auth-header-btn').textContent=email.split('@')[0];$('auth-modal').close()}}catch(err){fb.hidden=false;fb.textContent=err.message||'Authentication error'}};checkAuthSession();`;

export function registerUiRoutes(app: FastifyInstance){app.get("/",async(_r,reply)=>reply.type("text/html; charset=utf-8").header("Cache-Control","no-store").send(html));app.get("/ui/styles.css",async(_r,reply)=>reply.type("text/css; charset=utf-8").header("Cache-Control","no-store").send(css+trackingCss+extremeLeverageCss+orderGuidanceCss+comparisonCss+marketHeroCss+modeAndAuthCss));app.get("/ui/app.js",async(_r,reply)=>reply.type("application/javascript; charset=utf-8").header("Cache-Control","no-store").send(trackingJs+feedAdapterJs+extremeLeverageJs+orderGuidanceJs+comparisonJs+marketHeroJs+modeAndAuthJs));}
